const incoming = $input.first()?.json ?? {};
let input = incoming.input ?? incoming;
if (typeof input === 'string') input = JSON.parse(input);

function parseArray(value, name) {
  if (typeof value === 'string') {
    try { value = JSON.parse(value); } catch { throw new Error(name + ' must be valid JSON'); }
  }
  if (!Array.isArray(value)) throw new Error(name + ' must be an array');
  return value;
}

const suiteId = String(input.suite_id ?? '').trim();
if (!suiteId) throw new Error('Missing required input: suite_id');

let dryRun = input.dry_run;
if (typeof dryRun === 'string') {
  if (dryRun.trim().toLowerCase() === 'true') dryRun = true;
  else if (dryRun.trim().toLowerCase() === 'false') dryRun = false;
}
if (typeof dryRun !== 'boolean') throw new Error('dry_run must be explicitly boolean');

const allowedHosts = parseArray(input.allowed_hosts, 'allowed_hosts').map(v => String(v).trim().toLowerCase()).filter(Boolean);
if (!allowedHosts.length) throw new Error('allowed_hosts must be non-empty');
if (allowedHosts.some(h => h.includes('/') || h.includes(':'))) throw new Error('allowed_hosts must contain hostnames only');

const cases = parseArray(input.cases, 'cases');
if (!cases.length || cases.length > 100) throw new Error('cases must contain 1 to 100 items');

const blockedHeaders = new Set(['authorization','cookie','set-cookie','x-api-key','x-n8n-api-key','x-sc-proxy-token','x-line-signature']);
const ids = new Set();

return cases.map((testCase, index) => {
  if (!testCase || typeof testCase !== 'object' || Array.isArray(testCase)) throw new Error('Invalid case at index ' + index);
  const caseId = String(testCase.case_id ?? '').trim();
  if (!caseId) throw new Error('case_id is required at index ' + index);
  if (ids.has(caseId)) throw new Error('Duplicate case_id: ' + caseId);
  ids.add(caseId);

  const method = String(testCase.method ?? 'POST').trim().toUpperCase();
  if (!['GET','POST','PUT','PATCH','DELETE'].includes(method)) throw new Error('Unsupported method for ' + caseId);

  let url;
  try { url = new URL(String(testCase.url ?? '')); } catch { throw new Error('Invalid URL for ' + caseId); }
  if (url.protocol !== 'https:') throw new Error('Only HTTPS is allowed for ' + caseId);
  if (!allowedHosts.includes(url.hostname.toLowerCase())) throw new Error('Host is not allowlisted for ' + caseId);

  const requestHeaders = testCase.headers && typeof testCase.headers === 'object' && !Array.isArray(testCase.headers) ? testCase.headers : {};
  for (const key of Object.keys(requestHeaders)) {
    if (blockedHeaders.has(key.toLowerCase())) throw new Error('Secret-capable header is blocked for ' + caseId + ': ' + key);
  }

  const expectedStatus = Number(testCase.expected_status ?? 200);
  if (!Number.isInteger(expectedStatus) || expectedStatus < 100 || expectedStatus > 599) throw new Error('Invalid expected_status for ' + caseId);

  return {
    json: {
      suite_id: suiteId,
      dry_run: dryRun,
      requested_cases: cases.length,
      case_index: index + 1,
      case_id: caseId,
      method,
      url: url.toString(),
      request_headers: requestHeaders,
      request_body: testCase.body ?? {},
      expected_status: expectedStatus,
      expected_body_contains: testCase.expected_body_contains === undefined ? null : String(testCase.expected_body_contains)
    },
    pairedItem: { item: 0 }
  };
});

const response = $input.first()?.json ?? {};
const source = $('Validate and Expand Cases').item.json;
const statusCode = Number(response.statusCode ?? response.status ?? 0);
const body = response.body ?? response.data ?? response;
const serialized = typeof body === 'string' ? body : JSON.stringify(body);
const statusMatches = statusCode === source.expected_status;
const contentMatches = source.expected_body_contains === null || serialized.includes(source.expected_body_contains);
return [{ json: {
  suite_id: source.suite_id,
  dry_run: false,
  requested_cases: source.requested_cases,
  case_index: source.case_index,
  case_id: source.case_id,
  expected_status: source.expected_status,
  actual_status: statusCode,
  expected_body_contains: source.expected_body_contains,
  passed: statusMatches && contentMatches,
  status: statusMatches && contentMatches ? 'passed' : 'failed',
  response_excerpt: serialized.slice(0, 300).replace(/(bearer\s+)[^\s\"']+/gi, '$1[REDACTED]').replace(/(token|secret|password|authorization|cookie)([\"']?\s*[:=]\s*[\"']?)[^\"',}\s]+/gi, '$1$2[REDACTED]')
} }];

const rows = $input.all().map(item => item.json);
const first = rows[0] ?? {};
const planned = rows.filter(r => r.status === 'planned').length;
const passed = rows.filter(r => r.status === 'passed').length;
const failed = rows.filter(r => r.status === 'failed').length;
return [{ json: {
  ok: failed === 0,
  status: first.dry_run ? 'dry_run_completed' : (failed ? 'validation_failed' : 'validation_passed'),
  suite_id: first.suite_id,
  dry_run: Boolean(first.dry_run),
  requested_cases: rows.length,
  planned_cases: planned,
  passed_cases: passed,
  failed_cases: failed,
  results: rows.map(r => ({ case_id: r.case_id, status: r.status, expected_status: r.expected_status, actual_status: r.actual_status, response_excerpt: r.response_excerpt ?? null })),
  next_action: first.dry_run ? 'Review the plan, then run the same suite with dry_run=false.' : (failed ? 'Review failed cases; do not close M2.' : 'Capture sanitized execution evidence and reconcile the M2 Gate register.')
} }];
